package br.com.juh.kwaifacil;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.provider.Settings;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout box,list;TextView status;CheckBox automatic;Handler h=new Handler(Looper.getMainLooper());String rendered="";Runnable refresh;
 public void onCreate(Bundle b){super.onCreate(b);QueueStore.init(this);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);box=new LinearLayout(this);box.setOrientation(1);box.setPadding(32,40,32,30);box.setBackgroundColor(0xff10182b);ScrollView scroll=new ScrollView(this);scroll.addView(box);setContentView(scroll);
 ImageView icon=new ImageView(this);icon.setImageResource(getResources().getIdentifier("app_mascot","drawable",getPackageName()));icon.setScaleType(ImageView.ScaleType.FIT_CENTER);box.addView(icon,new LinearLayout.LayoutParams(160,160));text("Kwai Fácil",30);text("Fila organizada • revisão segura • publicação acompanhada",17);text("Use nomes iguais: 001.mp4 + 001.txt. Legendas em UTF-8; a extensão .TXT também é aceita. Capa opcional no TXT: CAPA_SEGUNDOS=3. Mantenha o celular desbloqueado e confira o primeiro envio.",14);
 button("Escolher pasta de vídeos",()->{if(QueueStore.running||QueueStore.importing){toast("Pause a fila ou aguarde a leitura.");return;}startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),11);});
 button("Ativar assistente",()->new AlertDialog.Builder(this).setTitle("Acessibilidade").setMessage("Durante a fila iniciada por você, o assistente lê as telas do Kwai e executa os passos de publicação. Vídeos e legendas só são enviados ao Kwai. Você pode pausar ou desativar o serviço.").setPositiveButton("Configurações",(d,w)->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))).setNegativeButton("Cancelar",null).show());
 automatic=new CheckBox(this);automatic.setTextColor(-1);automatic.setText("Publicar a fila automaticamente");box.addView(automatic);button("Iniciar / continuar fila",()->begin());button("Pausar / parar",()->QueueStore.pause("Fila pausada. Revise o item em andamento antes de continuar."));status=text("",16);list=new LinearLayout(this);list.setOrientation(1);box.addView(list);
 refresh=()->{String s=QueueStore.notice+"\n"+Run.status;status.setText(s);String key="";for(QueueStore.Item x:QueueStore.items)key+=x.name+x.state+x.caption;if(!key.equals(rendered)){rendered=key;list.removeAllViews();for(int i=0;i<QueueStore.items.size();i++){final int n=i;QueueStore.Item x=QueueStore.items.get(i);Button row=new Button(this);row.setText(x.name+" · "+x.state);list.addView(row);row.setOnClickListener(v->review(n));}}h.postDelayed(refresh,750);};h.post(refresh);}
 TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextColor(-1);v.setTextSize(size);v.setPadding(0,10,0,12);box.addView(v);return v;}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);box.addView(b);b.setOnClickListener(v->r.run());}
 void review(int i){QueueStore.Item x=QueueStore.items.get(i);AlertDialog.Builder d=new AlertDialog.Builder(this).setTitle(x.name).setMessage(x.state+"\n\n"+x.caption).setNegativeButton("Fechar",null);if(!QueueStore.running&&x.state.equals("Precisa de atenção")){d.setPositiveButton("Conferi no perfil: publicou",(a,w)->{x.state="Publicado";QueueStore.save();}).setNeutralButton("Conferi: não publicou",(a,w)->new AlertDialog.Builder(this).setMessage("Só tente novamente depois de conferir o perfil do Kwai. Isso evita publicar o mesmo vídeo duas vezes.").setPositiveButton("Tentar novamente",(a2,w2)->{x.state="Pendente";x.confirmationRetries=0;QueueStore.save();}).setNegativeButton("Cancelar",null).show());}d.show();}
 void begin(){if(QueueStore.importing){toast("Aguarde a leitura da pasta.");return;}if(QueueStore.running){toast("Fila já está em andamento.");return;}if(KwaiService.instance==null){toast("Ative a acessibilidade primeiro.");return;}if(QueueStore.uncertain()){toast("Revise o item que precisa de atenção antes de continuar.");return;}if(QueueStore.pending()<0){toast("Não há vídeos pendentes com legenda.");return;}
 Intent probe=new Intent(Intent.ACTION_SEND).setType("video/*");ArrayList<ResolveInfo> choices=new ArrayList<>();for(ResolveInfo r:getPackageManager().queryIntentActivities(probe,PackageManager.MATCH_ALL)){String pkg=r.activityInfo.packageName;if(pkg.equals("com.kwai.video")||pkg.equals("com.smile.gifmaker")||r.loadLabel(getPackageManager()).toString().toLowerCase(Locale.ROOT).contains("kwai"))choices.add(r);}if(choices.isEmpty()){toast("Kwai não encontrado para receber vídeo.");return;}String[] names=new String[choices.size()];for(int i=0;i<names.length;i++)names[i]=choices.get(i).loadLabel(getPackageManager()).toString();new AlertDialog.Builder(this).setTitle("Iniciar fila no Kwai").setItems(names,(d,i)->{ResolveInfo r=choices.get(i);QueueStore.destination=new ComponentName(r.activityInfo.packageName,r.activityInfo.name);Run.auto=automatic.isChecked();QueueStore.running=true;QueueStore.launch(this);}).setNegativeButton("Cancelar",null).show();}
 protected void onActivityResult(int req,int result,Intent d){super.onActivityResult(req,result,d);if(req==11&&result==RESULT_OK&&d!=null){Uri tree=d.getData();try{getContentResolver().takePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION);QueueStore.importing=true;QueueStore.notice="Lendo pasta…";new Thread(()->{try{QueueStore.scan(tree);}catch(Exception e){QueueStore.notice="Não foi possível ler: "+e.getMessage();}finally{QueueStore.importing=false;}}).start();}catch(Exception e){toast("Não foi possível autorizar a pasta.");}}}
 protected void onDestroy(){h.removeCallbacksAndMessages(null);super.onDestroy();}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
